const eco2026 = { type: 'annale', organisme: 'ENSEA', annee: 2026, epreuve: 'ISE option économie, 2e composition de mathématiques', documentId: '6ac272e4316193dda86e4416' };
const eco2026premiere = { type: 'annale', organisme: 'ENSEA', annee: 2026, epreuve: 'ISE option économie, 1re composition de mathématiques', documentId: '6ac272e1316193dda86e440f' };
const eco2024 = { type: 'annale', organisme: 'ENSEA', annee: 2024, epreuve: 'ISE option économie, 2e composition de mathématiques', documentId: '6ac272cd316193dda86e43d7' };
const rappels = {
  'IEL-MAT': mc('Lire une matrice', 'Une matrice est un tableau rectangulaire de nombres. Sa taille est lignes × colonnes. Le coefficient aᵢⱼ se trouve à la ligne i et à la colonne j.', 'Lire la ligne avant la colonne.'),
  'IEL-OP': mc('Opérations simples', 'Somme et multiplication par un réel se font coefficient par coefficient. La transposée échange les lignes et les colonnes. La trace est la somme des coefficients diagonaux d’une matrice carrée.', '(AB)ᵀ = BᵀAᵀ.'),
  'IEL-PROD': mc('Produit matriciel', 'Pour calculer le coefficient (i,j) de AB, multiplier les termes de la ligne i de A par ceux de la colonne j de B, puis additionner. Les dimensions intérieures doivent coïncider.', 'L’ordre des facteurs compte.'),
  'IEL-SYS': mc('Système linéaire', 'Une solution doit vérifier toutes les équations à la fois. On peut écrire AX = B, où X regroupe les inconnues et B les seconds membres.', 'Tester chaque équation.'),
  'IEL-GAUSS': mc('Éliminer une inconnue', 'Échanger deux lignes, multiplier une ligne par un nombre non nul ou lui ajouter un multiple d’une autre ligne conserve les solutions. Appliquer la même opération au second membre.', 'Créer des zéros sous chaque pivot.'),
  'IEL-RANG': mc('Rang et pivots', 'Le rang est le nombre de pivots après élimination de Gauss sur les coefficients. Une ligne 0 = c, avec c non nul, rend le système incompatible. Sans contradiction, chaque inconnue sans pivot est libre.', 'Distinguer coefficients et second membre.'),
  'IEL-INV': mc('Inverser par Gauss', 'Pour une matrice carrée A, réduire le bloc [A | I] par opérations de lignes. Si le bloc gauche devient I, le bloc droit est A⁻¹. Sinon A n’est pas inversible.', 'Vérifier le produit avec A.'),
  'IEL-DET': mc('Déterminant', 'Pour une matrice 2 × 2 de lignes (a,b) et (c,d), le déterminant est ad − bc. En ordre 3, développer par une ligne avec les signes +, −, +. Une matrice carrée est inversible exactement quand son déterminant est non nul.', 'Un déterminant nul signale une dépendance.'),
  'IEL-ESP': mc('Sous-espace vectoriel', 'Un sous-espace contient le vecteur nul et reste stable quand on additionne ses éléments ou quand on les multiplie par un réel. Les solutions d’équations linéaires homogènes en donnent des exemples.', 'Tester le zéro puis les deux stabilités.'),
  'IEL-BASE': mc('Base et dimension', 'Une famille est libre si la seule combinaison nulle a tous ses coefficients nuls. Elle est génératrice si ses combinaisons couvrent l’espace. Une base est libre et génératrice ; son nombre de vecteurs est la dimension.', 'Dans une base, les coordonnées sont uniques.'),
  'IEL-APP': mc('Noyau, image et rang', 'Pour une application linéaire T, le noyau est l’ensemble des u tels que T(u) = 0. L’image regroupe les sorties possibles. En dimension finie, dim(départ) = dim(noyau) + rang(T).', 'Le rang est la dimension de l’image.'),
  'IEL-SOMME': mc('Décomposition directe', 'E = F ⊕ G signifie que tout vecteur s’écrit de manière unique f + g. La projection sur F parallèlement à G garde f ; la symétrie correspondante donne f − g.', 'La projection vérifie p² = p.'),
  'IEL-VP': mc('Valeurs propres', 'Un vecteur propre u est non nul et vérifie Au = λu. Pour chercher les valeurs propres, résoudre det(A − λI) = 0, puis résoudre (A − λI)u = 0.', 'Le vecteur nul n’est jamais propre.'),
  'IEL-DIAG': mc('Diagonalisation', 'Une matrice est diagonalisable si l’on peut former une base de vecteurs propres. En les rangeant en colonnes dans P, on obtient AP = PD, donc A = PDP⁻¹.', 'Compter les vecteurs propres indépendants.'),
  'IEL-PASS': mc('Changer de base', 'Si P contient les nouveaux vecteurs de base en anciennes coordonnées, les anciennes coordonnées sont P fois les nouvelles. La matrice de l’application dans la nouvelle base est P⁻¹AP.', 'Pour les puissances : Aⁿ = PDⁿP⁻¹.'),
};
const fiche = (code, niveau, notion) => ({ code, niveau, notions: [notion], source: original, miniCours: rappels[notion] });
const question = (code, notion, consigne, options, bonne, explication) => b.question(qcm({ ...fiche(code, 1, notion), consigne, options, bonne, explication }));

